Error en d.chiCol[i, j] = 0 : objeto de tipo 'closure' no es subconjunto


d.chiCol<- function(A)
{
m <- dim(A)[2]
n <- dim(A)[1]
B <- prop.table(A,2)
C <- prop.table(A)
pesos <- apply(C,1,sum)
dchi.Col <- matrix(,m,m)
for (i in 1:m)
{
 for(j in 1:m)
  {
  if(i==j)
      d.chiCol[i,j]=0
    else
      x <- (B[,i]-B[,j])^2
      val <- x/pesos
      dchi.Col[i,j]=sqrt(sum(val))
  }
}
dchi.Col
}
